// Focused, browser-independent geometry/state regression for the 1:1 exemplar.
const assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs'),path=require('node:path');
const {make}=require('./audit-mechanics-four.cjs');
const results=[];function test(name,fn){try{fn();results.push({name,ok:true})}catch(e){results.push({name,ok:false,error:e.stack})}}
function sample(state={},yaw=45,pitch=35.264){const t=make('elevator');vm.runInContext(`const oldBox=box,oldRod=rod,oldLine=line,oldCyl=cyl,oldCylX=cylX;box=(...a)=>'<g data-box="'+a.slice(0,6).join(',')+'">'+oldBox(...a)+'</g>';rod=(...a)=>'<g data-rod="'+a[0].concat(a[1],a[2]).join(',')+'">'+oldRod(...a)+'</g>';globalThis.qaLine=(...a)=>'<g data-line="'+a[0].flat().join(',')+'">'+oldLine(...a)+'</g>';cyl=(...a)=>'<g data-cyl="'+a.slice(0,5).join(',')+'">'+oldCyl(...a)+'</g>';cylX=(...a)=>'<g data-cylx="'+a.slice(0,5).join(',')+'">'+oldCylX(...a)+'</g>';`,t.ctx);vm.runInContext(fs.readFileSync(path.join(__dirname,'../dist/scenes/elevator.js'),'utf8').replace(/\bline\(/g,'qaLine('),t.ctx);vm.runInContext('globalThis.cfg=window.SCENES.elevator();cfg.state.pal=cfg.palette;',t.ctx);t.cfg=t.ctx.cfg;t.state=t.cfg.state;Object.assign(t.state,state);t.ctx.draw(yaw,pitch);return t;}
const layer=(t,id)=>{const l=t.ctx.layers().find(p=>p.key===id);assert(l,'Missing layer '+id);return l};
const attrs=(l,key)=>[...l.svg.matchAll(new RegExp(`data-${key}="([^"]+)"`,'g'))].map(m=>m[1].split(',').map(Number));
const near=(a,b,msg)=>assert(Math.abs(a-b)<1e-7,msg||`${a} != ${b}`);
const xyz=a=>Array.from({length:a.length/3},(_,i)=>a.slice(i*3,i*3+3));
const vectorNear=(a,b)=>a.forEach((n,i)=>near(n,b[i]));
const positions=[0,.001,8,16.5,32.999,33,49.5,65.999,66];
function checkDoors(t,prefix,base,open){for(const [i,key]of ['leftOuter','leftInner','rightInner','rightOuter'].entries()){const b=attrs(layer(t,prefix+'door'+key),'box')[0];near(b[4]-b[1],6);near(b[1],[15-6*open,21-12*open,27+12*open,33+6*open][i]);near(b[2],base+1.5);near(b[5],base+26);assert(!layer(t,prefix+'door'+key).svg.includes('clip-path'),'A flat doorway clip must not erase the rigid leaf side face');assert(layer(t,prefix+'pocketFront'+(i<2?'left':'right')));assert(layer(t,prefix+'pocketBack'+(i<2?'left':'right')));}}
test('Continuous 1:1 rope: both legs meet the upper semicircle and total length stays fixed',()=>{let length;for(const pos of positions){const t=sample({pos});const car=attrs(layer(t,'cable'),'rod')[0],weight=attrs(layer(t,'weightCable'),'rod')[0],upper=attrs(layer(t,'upperRope'),'rod'),arc=xyz(attrs(layer(t,'upperRope'),'line')[0]);vectorNear(car.slice(3,6),upper[0].slice(0,3));vectorNear(weight.slice(3,6),upper[1].slice(0,3));vectorNear(upper[0].slice(3,6),arc[0]);vectorNear(upper[1].slice(3,6),arc.at(-1));for(const p of arc){near(p[0],30);near(Math.hypot(p[1]-41.5,p[2]-123),8.5);assert(p[2]>=123-1e-8)}const current=(123-car[2])+(123-weight[2])+Math.PI*8.5;if(length==null)length=current;near(current,length);near(car[2],35.9+pos);near(weight[2],98.2-pos);const carHitch=attrs(layer(t,'carHitchTip'),'cyl')[0],weightHitch=attrs(layer(t,'counterweight'),'rod')[0];near(carHitch[3],car[2]);near(weightHitch[5],weight[2]);}});
test('Counterweight moves the same distance in the opposite direction and clears car, slabs and roof',()=>{let last;for(const pos of positions){const t=sample({pos}),cw=attrs(layer(t,'counterweight'),'box'),cab=attrs(layer(t,'cabintop'),'box')[0],car=attrs(layer(t,'cabinfloor'),'box')[0];if(last){near(car[2]-last.car,pos-last.pos);near(cw[0][2]-last.weight,-(pos-last.pos));}for(const b of cw){assert(b[1]>45,'Counterweight intersects cabin');assert(b[3]<40,'Counterweight intersects landing slabs');assert(b[2]>5&&b[5]<109,'Counterweight intersects plinth or roof');}assert(cab[5]<109);last={pos,car:car[2],weight:cw[0][2]};}});
test('Sheave has tangent rope paths, stays above the slab and turns with no-slip 1:1 travel',()=>{for(const pos of positions){const t=sample({pos}),sheave=layer(t,'tractionSheave'),c=attrs(sheave,'cylx')[0],spoke=xyz(attrs(sheave,'line')[0]);near(c[2],41.5);near(c[3],123);assert(c[3]-c[4]>114);const theta=-pos/8.5;near(spoke[1][1],41.5+6.6*Math.cos(theta));near(spoke[1][2],123+6.6*Math.sin(theta));assert(!t.ctx.layers().some(p=>p.key==='winch'));}});
test('Wheel tangent velocity agrees with both upward and downward cabin travel',()=>{for(const pos of[.1,16.5,33,49.5,65.9])for(const ds of[-.00001,.00001]){const a=sample({pos}),b=sample({pos:pos+ds});const angle=t=>{const p=xyz(attrs(layer(t,'tractionSheave'),'line')[0])[1];return Math.atan2(p[2]-123,p[1]-41.5)};const delta=Math.atan2(Math.sin(angle(b)-angle(a)),Math.cos(angle(b)-angle(a)));near(delta,-ds/8.5);const carTangentDz=-8.5*delta,weightTangentDz=8.5*delta;near(carTangentDz,ds);near(weightTangentDz,-ds);assert.equal(Math.sign(carTangentDz),Math.sign(ds));assert.equal(Math.sign(weightTangentDz),-Math.sign(ds));}});
test('Two actual roof apertures surround both rope legs at all camera angles',()=>{for(const yaw of[0,45,90,135,180,225,270,315])for(const pitch of[6,35.264,78]){const t=sample({},yaw,pitch),roof=layer(t,'roof').svg;const top=roof.match(/<path d="([^"]+)" fill="[^"]+" fill-rule="evenodd"/);assert(top);assert.equal(top[1].split('M').length,4,'Expected one top outline and two holes');for(const y of[33,50])for(const [x,Y]of[[29.1,y-.9],[30.9,y+.9]]){const q=t.ctx.project(x,Y,114);assert(top[1].includes(q[0].toFixed(1)+' '+q[1].toFixed(1)));}for(const key of['cable','weightCable'])assert(attrs(layer(t,key),'rod')[0][6]<.9);}});
test('Counterweight guide shoes bridge each rail to its own frame',()=>{const t=sample();for(const [i,x]of[20,36].entries()){const rail=attrs(layer(t,'weightRail'+x),'rod')[0];near(rail[0],x);near(rail[1],50);const shoes=attrs(layer(t,'counterweight'),'box').slice(-4).slice(i*2,i*2+2);for(const b of shoes){assert(b[0]<x&&b[3]>x);assert(x===20?b[3]>21:b[0]<35);assert(b[1]<50&&b[4]>50);}}});
test('Fixed-width, physically pocket-occluded landing doors open only at the aligned stationary floor',()=>{for(let floor=1;floor<=3;floor++)for(const door of[0,.2,.5,.8,1]){const t=sample({floor,pos:(floor-1)*33,door});checkDoors(t,'',6.5+(floor-1)*33,door);for(let i=0;i<3;i++)checkDoors(t,'landing'+i,6.5+i*33,i===floor-1?door:0);}for(const pos of positions){const t=sample({pos,phase:'moving',door:1});for(let i=0;i<3;i++)checkDoors(t,'landing'+i,6.5+i*33,0);}for(const pos of[.01,16.5,32.99,33.01,49.5,65.99]){const t=sample({pos,phase:'opening',door:1});for(let i=0;i<3;i++)checkDoors(t,'landing'+i,6.5+i*33,0);}});
test('Visible lock bolts engage while travelling and release only the levelled landing',()=>{for(let floor=1;floor<=3;floor++)for(const phase of['idle','opening','closing','manualClose','moving'])for(const door of[0,.5,1]){const t=sample({floor,pos:(floor-1)*33,phase,door});for(let i=0;i<3;i++){const bolt=attrs(layer(t,'landingLock'+i),'rod')[0];const locked=phase==='moving'||i!==floor-1||door===0&&phase!=='opening';near(bolt[1],locked?26.5:24.5);near(bolt[4],locked?30.6:28.6);assert(locked?bolt[4]>30:bolt[4]<30);}}});
test('Default mode has no inspection controls; exploration adds four real labelled parts',()=>{const t=make('elevator');assert.equal(t.state.exploreOpen,false);assert.equal(t.state.inspectPart,null);assert(!t.ctx.draw().includes('data-act="inspect"'));t.cfg.exploration.onToggle(t.state,true,t.ui);let svg=t.ctx.draw();assert.equal((svg.match(/data-act="inspect"/g)||[]).length,4);for(const {id,label}of t.cfg.exploration.parts){assert(svg.includes('data-part="'+id+'"'));assert(svg.includes('观察'+label));}t.cfg.exploration.onToggle(t.state,false,t.ui);assert(!t.ctx.draw().includes('data-act="inspect"'));assert.equal(t.steps.size,0);});
test('Inspection changes only presentation; closing clears selection and reset keeps panel context',()=>{const t=make('elevator'),views=[];t.ui.camTo=(...a)=>views.push(a);t.cfg.acts.inspect(t.state,{dataset:{part:'drive'}},t.ui);assert.equal(t.state.inspectPart,null);t.cfg.exploration.onToggle(t.state,true,t.ui);for(const {id}of t.cfg.exploration.parts){t.cfg.acts.inspect(t.state,{dataset:{part:id}},t.ui);assert.equal(t.state.inspectPart,id);assert.equal(t.state.pos,0);assert.equal(t.state.door,1);assert.equal(t.state.trips,0);}assert.equal(views.length,4);t.cfg.exploration.onSelect(t.state,'not-a-part',t.ui);assert.equal(t.state.inspectPart,'locks');t.click('前往三楼');t.tick(2);t.click('回到一楼');t.tick(10);assert.equal(t.state.exploreOpen,true);assert.equal(t.state.inspectPart,'locks');assert.equal(t.state.floor,1);assert.equal(t.steps.size,0);t.cfg.exploration.onToggle(t.state,false,t.ui);assert.equal(t.state.inspectPart,null);});
test('Live short descriptions distinguish departure, ascending, descending and arrival',()=>{const t=make('elevator'),d=id=>t.cfg.exploration.describe(t.state,id);for(const id of[null,...t.cfg.exploration.parts.map(p=>p.id)]){assert(d(id).title);assert(d(id).text.length<150);}Object.assign(t.state,{phase:'closing',door:.5});assert(d('drive').text.includes('不动'));assert(d('locks').text.includes('尚未'));assert(d('cabin').text.includes('正在关闭'));assert(!d('cabin').text.includes('一起打开'));Object.assign(t.state,{phase:'moving',pos:16.5,target:3});assert(d('counterweight').text.includes('上升，对重就下降'));assert(d('locks').text.includes('不会解锁'));Object.assign(t.state,{pos:49.5,target:1});assert(d('counterweight').text.includes('下降，对重就上升'));Object.assign(t.state,{phase:'opening',floor:3,pos:66,door:.5});assert(d('locks').text.includes('3楼'));assert(d('cabin').text.includes('平层'));});
test('Repeated floor, door and inspection inputs preserve interlocks, FIFO calls and driver cleanup',()=>{const t=make('elevator');let seed=571;for(let i=0;i<250;i++){seed=seed*16807%2147483647;const labels=['前往一楼','前往二楼','前往三楼','开门','关门'];t.click(labels[seed%5]);if(i%7===0)t.cfg.exploration.onToggle(t.state,!t.state.exploreOpen,t.ui);if(i%11===0&&t.state.exploreOpen)t.cfg.exploration.onSelect(t.state,['drive','counterweight','cabin','locks'][seed%4],t.ui);t.tick((seed%80)/120);assert(t.state.pos>=0&&t.state.pos<=66);assert(t.state.door>=0&&t.state.door<=1);assert.equal(new Set(t.state.queue).size,t.state.queue.length);if(t.state.phase==='moving')assert.equal(t.state.door,0);assert(t.steps.size<=2);}t.tick(60);assert.equal(t.state.phase,'idle');assert.equal(t.steps.size,0);});
test('Finite SVG and four stable inspection targets at endpoints and mid-travel in 24 views and all palettes',()=>{const t=make('elevator');t.state.exploreOpen=true;for(const pal of['mint','mustard','tomato','cobalt','blush'])for(const yaw of[0,45,90,135,180,225,270,315])for(const pitch of[6,35.264,78])for(const pos of[0,16.5,33,49.5,66]){Object.assign(t.state,{pal,pos,floor:Math.round(pos/33)+1,target:3,phase:pos%33?'moving':'idle',door:pos%33?0:.5,inspectPart:['drive','counterweight','cabin','locks'][Math.floor(pos)%4]});const svg=t.ctx.draw(yaw,pitch);assert(!/NaN|Infinity|undefined/.test(svg),`${pal}/${yaw}/${pitch}/${pos}`);assert.equal((svg.match(/data-act="inspect"/g)||[]).length,4);assert.equal(new Set(t.ctx.layers().map(p=>p.key)).size,t.ctx.layers().length);}});
console.log(JSON.stringify(results,null,2));fs.writeFileSync(path.join(__dirname,'elevator-traction-results.json'),JSON.stringify({at:new Date().toISOString(),browser:false,results},null,2));if(results.some(r=>!r.ok))process.exitCode=1;
